// Pull the CSRF token + session cookie out of the login page.
// Credentials are NOT here - they are injected by the Custom Auth
// credential on the next node, so nothing secret lives in this file.
const res = $input.first().json;
const html = String(res.body || res.data || '');
let sc = res.headers?.['set-cookie'] || [];
if (!Array.isArray(sc)) sc = [sc];

const cookie = (name) => {
  for (const c of sc) {
    if (typeof c === 'string' && c.startsWith(name + '='))
      return c.split(';')[0].slice(name.length + 1);
  }
  return '';
};

const sessionId = cookie('ASP.NET_SessionId');
const csrfCookie = cookie('__RequestVerificationToken');

// hidden inputs (the anti-forgery token lives here)
const hidden = {};
for (const tag of html.match(/<input\b[^>]*>/gi) || []) {
  const attr = (a) => (tag.match(new RegExp(a + '=["\']([^"\']*)["\']', 'i')) || [])[1] || '';
  if ((attr('type') || 'text').toLowerCase() === 'hidden' && attr('name')) {
    hidden[attr('name')] = attr('value');
  }
}

if (!hidden.__RequestVerificationToken) {
  throw new Error('No __RequestVerificationToken on the login page - the form layout changed.');
}

return [{
  json: {
    BASE: $('Config').first().json.BASE,
    AUCTION_PATH: $('Config').first().json.AUCTION_PATH,
    token: hidden.__RequestVerificationToken,
    cookieHeader: `ASP.NET_SessionId=${sessionId}; __RequestVerificationToken=${csrfCookie}`,
  },
}];

// Turn the login response into an authenticated cookie header.
const res = $input.first().json;
let sc = res.headers?.['set-cookie'] || [];
if (!Array.isArray(sc)) sc = [sc];

const cookie = (name) => {
  for (const c of sc) {
    if (typeof c === 'string' && c.startsWith(name + '='))
      return c.split(';')[0].slice(name.length + 1);
  }
  return '';
};

const aspxAuth = cookie('.ASPXAUTH');
if (!aspxAuth) {
  throw new Error(
    'Login failed - no .ASPXAUTH cookie returned. Check the GovEase Login ' +
    'credential, or the login form field names have changed. Status: ' + res.statusCode);
}

const sessionId = cookie('ASP.NET_SessionId') || $('Extract CSRF + Cookies').first().json.cookieHeader
  .match(/ASP\.NET_SessionId=([^;]+)/)?.[1] || '';

return [{
  json: {
    BASE: $('Config').first().json.BASE,
    AUCTION_PATH: $('Config').first().json.AUCTION_PATH,
    authCookie: `ASP.NET_SessionId=${sessionId}; .ASPXAUTH=${aspxAuth}`,
  },
}];

// ============================================================

// ============================================================
const rawHtml = $input.first().json.data || "";
if (!rawHtml || rawHtml.length < 500) {
  throw new Error("Auctions page returned no usable HTML - session likely expired or the page moved.");
}

const results = [];
// Regex to isolate each individual property row in the table
const rowRegex = /<tr role="row"[^>]*id=bid-status-for-row-\d+>([\s\S]*?)<\/tr>/gi;
let match;

while ((match = rowRegex.exec(rawHtml)) !== null) {
  const rowHtml = match[1];

  // Safe tag stripping helper function
  const cleanTd = (str) => {
    return (str || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  };

  // Isolate every column (<td>) in the row
  const tdMatches = rowHtml.match(/<td[^>]*>([\s\S]*?)<\/td>/gi) || [];
  if (tdMatches.length < 9) continue;

  const tds = tdMatches.map(cleanTd);

  // Extract specific fields based on GovEase's hidden HTML structure
  const itemId = tds[2] || '';
  const parcelNumber = tds[3] || 'N/A';
  const owner = tds[4] || 'N/A';

  // Parse Face Value to a clean number
  let faceValue = tds[5] || '$0.00';
  faceValue = parseFloat(faceValue.replace(/[^\d.]/g, '')) || 0;

  // Grab the hidden physical address (Column 7)
  let address = tds[6];
  if (!address || address.length < 2) {
      address = `Parcel: ${parcelNumber}`; // Fallback if no street address exists
  }

  // Grab the hidden auction name (Column 8) to parse the exact County
  const auctionName = tds[7] || '';
  let county = "N/A - Check Listing";
  const countyMatch = auctionName.match(/([A-Za-z\s]+)\s+County/i);
  if (countyMatch) {
     county = countyMatch[1].trim() + " County";
  }

  // Extract URL Path to build a direct clickable link and identify the State
  const linkMatch = rowHtml.match(/<A HREF="([^"]+)"/i);
  const urlPath = linkMatch ? linkMatch[1] : '';
  const fullUrl = urlPath ? `https://liveauctions.govease.com${urlPath}` : "https://www.govease.com/tax-sale-property-auctions";

  // Pluck the State dynamically out of the URL (e.g., "/al/...")
  let state = "";
  const stateMatch = urlPath.match(/^\/([a-z]{2})\//i);
  if (stateMatch) {
      state = stateMatch[1].toUpperCase();
  }

  // Generate robust Unique ID
  const uniqueId = `govease|${county}|${address}|${itemId}`.toLowerCase().replace(/[^a-z0-9|]/g, '');
  const isQuality = (
  state !== "" &&
  county !== "N/A - Check Listing" &&
  address.length > 3
);
if (!isQuality) continue;


  results.push({
    json: {
      property_address: address,
      county: county,
      state: state,
      source: "GovEase",
      status: "Upcoming",
      sale_date: "Check Listing",
      bidding_date: "Check Listing",
      bidding_time: "Check Listing",
      current_bid: faceValue,
      auction_url: fullUrl,
      time_remaining: "",
      unique_id: uniqueId
    }
  });
}

if (results.length === 0) {
  return [{ json: { error: "No properties parsed from HTML. Site layout may have changed.", source: "GovEase", unique_id: "skip" } }];
}

console.log(`✅ GovEase: ${results.length} properties extracted from HTML`);
return results;
